<?php
namespace App\Providers;
use App\Actions\Fortify\CreateNewUser;use App\Actions\Fortify\ResetUserPassword;use App\Actions\Fortify\UpdateUserPassword;use App\Actions\Fortify\UpdateUserProfileInformation;use App\Enums\UserStatus;use App\Models\User;use Illuminate\Cache\RateLimiting\Limit;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\RateLimiter;use Illuminate\Support\ServiceProvider;use Illuminate\Support\Str;use Laravel\Fortify\Fortify;
class FortifyServiceProvider extends ServiceProvider{public function boot():void{Fortify::createUsersUsing(CreateNewUser::class);Fortify::updateUserProfileInformationUsing(UpdateUserProfileInformation::class);Fortify::updateUserPasswordsUsing(UpdateUserPassword::class);Fortify::resetUserPasswordsUsing(ResetUserPassword::class);Fortify::authenticateUsing(function(Request $request){$user=User::where('email',$request->email)->first();return $user&&$user->status===UserStatus::Active&&Hash::check($request->password,$user->password)?$user:null;});Fortify::loginView(fn()=>view('auth.login'));Fortify::registerView(fn()=>view('auth.register'));Fortify::requestPasswordResetLinkView(fn()=>view('auth.forgot-password'));Fortify::resetPasswordView(fn(Request $r)=>view('auth.reset-password',['request'=>$r]));Fortify::verifyEmailView(fn()=>view('auth.verify-email'));Fortify::confirmPasswordView(fn()=>view('auth.confirm-password'));RateLimiter::for('login',fn(Request $r)=>Limit::perMinute(5)->by(Str::lower($r->input(Fortify::username())).'|'.$r->ip()));}}
